            if file.lower().endswith(('.jpg', '.jpeg', '.png', '.bmp')):
                total_images += 1
                try:
                    img_path = os.path.join(root, file)
                    with open(img_path, 'rb') as f:
                        Image.open(f).verify()
                except Exception as e:
