{"code": "from PIL import Image
import os

# Try a few different images to see if any are valid
test_images = []
for root, dirs, files in os.walk('data_small/101/train'):
    for file in files:
        if file.endswith('.jpg'):
            img_path = os.path.join(root, file)
            size = os.path.getsize(img_path)
            test_images.append((img_path, size))
            if len(test_images) >= 10:
                break
    if len(test_images) >= 10:
        break

print("Testing 10 random images:")
print("-" * 80)
for i, (img_path, size) in enumerate(test_images[:5]):
    print(f"\n{i+1}. {os.path.basename(img_path)} - Size: {size} bytes")
    try:
        with open(img_path, 'rb') as f:
            img = Image.open(f)
            # Try to get image properties without loading all data
            mode = getattr(img, 'mode', None)
            try:
                img.load()
                print(f"   Successfully loaded! Mode: {mode}, Size: {img.size}")
            except Exception as e2:
                print(f"   Could verify but failed to load: {e2}")
    except Exception as e:
        print(f"   Error: {type(e).__name__}")"}

